"""Deterministic edge-case scenarios + invalid-input probes."""
import json
import sys
sys.path.insert(0, '/workspace/fuzz')
sys.path.insert(0, '/workspace/submission')
import verify
from run_fuzz import subproc


def base_case(**kw):
    case = {
        'nodes': 3,
        'edges': [[0, 1, 5], [1, 2, 5], [0, 2, 3], [2, 0, 4]],
        'commodities': [
            {'source': 0, 'sink': 2, 'demand': 4, 'paths': [[0, 1], [2]]},
            {'source': 1, 'sink': 0, 'demand': 2, 'paths': [[3]]},
        ],
        'workers': [[0], [1]],
        'quorum': 1,
        'max_lag': 2,
        'relax': [1, 1],
        'rho': 2,
        'mode': 'route',
        'events': [{'op': 'audit'}],
    }
    case.update(kw)
    return case


SCENARIOS = {}

def scenario(fn):
    SCENARIOS[fn.__name__] = fn
    return fn


@scenario
def retune_dual_scaling():
    return {'cases': [base_case(events=[
        {'op': 'issue', 'id': 1, 'worker': 0},
        {'op': 'issue', 'id': 2, 'worker': 1},
        {'op': 'deliver', 'id': 1},
        {'op': 'deliver', 'id': 2},
        {'op': 'step'},
        {'op': 'retune', 'rho': 7},
        {'op': 'audit'},
        {'op': 'retune', 'rho': 2},
        {'op': 'audit'},
        {'op': 'issue', 'id': 3, 'worker': 0},
        {'op': 'deliver', 'id': 3},
        {'op': 'step'},
        {'op': 'retune', 'rho': 4},
        {'op': 'step'},
        {'op': 'audit'},
    ])]}


