@scenario
def multi_step_lag_chain():
    ev = []
    for i in range(6):
        ev.append({'op': 'issue', 'id': i, 'worker': i % 2})
        ev.append({'op': 'deliver', 'id': i})
        ev.append({'op': 'step'})
        if i % 2 == 0:
            ev.append({'op': 'retune', 'rho': 1 + (i % 8)})
        if i == 2:
            ev.append({'op': 'save', 'name': 7})
        if i == 4:
            ev.append({'op': 'restore', 'name': 7})
    ev.append({'op': 'audit'})
    return {'cases': [base_case(max_lag=1, events=ev)]}


INVALID = [
    ('empty', ''),
    ('ws', '   \n '),
    ('null', 'null'),
    ('array', '[]'),
    ('emptyobj', '{}'),
    ('cases-not-list', '{"cases":{}}'),
    ('extra-root-key', '{"cases":[],"z":1}'),
    ('dup-root-key', '{"cases":[],"cases":[]}'),
    ('trailing', '{"cases":[]} x'),
    ('bom', '\ufeff{"cases":[]}'),
    ('nan', '{"cases":[NaN]}'),
    ('inf', '{"cases":[Infinity]}'),
    ('hugefloat', '{"cases":[{"nodes":1e999}]}'),
    ('badutf8', b'{"cases":[\xff]}'),
    ('deep', '[' * 200 + ']' * 200),
]


def case_invalid(mutate):
    c = base_case()
    return {'cases': [mutate(c)]}


def build_invalid():
    out = list(INVALID)
    def m1(c):
        c['nodes'] = 2.0; return c
    def m2(c):
        c['nodes'] = True; return c
    def m3(c):
        c['edges'][0] = [0, 0, 1]; return c
    def m4(c):
        c['edges'][0] = [0, 1, -1]; return c
    def m5(c):
        c['edges'].append([0, 1, 2]); return c
    def m6(c):
        c['commodities'][0]['source'] = c['commodities'][0]['sink']; return c
    def m7(c):
        c['commodities'][0]['paths'] = [[0, 0]]; return c
    def m8(c):
        c['commodities'][0]['paths'] = [[1, 0]]; return c
    def m9(c):
        c['commodities'][0]['paths'] = [[2, 2]]; return c
    def m10(c):
