                        'demand': [], 'paths': [[0, 0, [1, 0]]]}]; return c
    def m28(c):
        c['events'] = [{'op': 'configure', 'mode': 'route', 'capacity': [],
                        'demand': [], 'paths': [[0, 3, None]]}]; return c
    def m29(c):
        c['commodities'][0]['paths'] = [[0, 1], [0, 1]]; return c
    def m30(c):
        c['events'] = [{'op': 'retune', 'rho': 9}]; return c
    def m31(c):
        c['events'] = [{'op': 'step', 'x': 1}]; return c
    def m32(c):
        c['events'] = [{'op': 'issue', 'id': 1, 'worker': 0},
                       {'op': 'deliver', 'id': 1, 'status': 'accepted'}]; return c
    def m33(c):
        c['edges'][0] = [0, 1, 1001]; return c
    def m34(c):
        c['events'] = [{'op': 'issue', 'id': 2000000000, 'worker': 0}]; return c
    def m35(c):
        c['nodes'] = 1; return c
    def m36(c):
        c['commodities'][0]['paths'] = [[0, 1, 1]]; return c  # repeat node 1
    def m37(c):
        c['events'] = [{'op': 'configure', 'mode': 'route', 'capacity': [],
                        'demand': [[0, 2], [0, 3]], 'paths': []}]; return c
    def m38(c):
        c['events'] = [{'op': 'issue', 'id': 1, 'worker': 0},
                       {'op': 'save', 'name': 1},
                       {'op': 'restore', 'name': 1},
                       {'op': 'issue', 'id': 1, 'worker': 0}]; return c
    def m39(c):
        c['relax'] = [1, 2]; return c   # b<=a? 2<=1 false -> invalid
    def m40(c):
        c['relax'] = [15, 8]; return c  # 8<=15<16 valid -> VALID! skip
    def m41(c):
        c['workers'] = [[], []]; return c  # commodity 0,1 not covered
    def m42(c):
        c['events'] = [{'op': 'configure', 'mode': 'route', 'capacity': [],
                        'demand': [], 'paths': [[0, 0, []]]}]; return c
    def m43(c):
