    def m46(c):
        c['max_lag'] = 13; return c
    def m47(c):
        del c['rho']; return c
    def m48(c):
        c['edges'] = [[0, 1, 1], [0, 1, 2]]; return c
    def m49(c):
        c['events'] = [{'op': 'configure', 'mode': 'route', 'capacity': [],
                        'demand': [], 'paths': [[0, 0, [0, 1]], [0, 1, [0, 1]]]}]; return c
    # m40 is valid; keep it out
    for name, fn in sorted(list(globals().items())):
        if name.startswith('m') and name[1:].isdigit():
            if name == 'm40':
                continue
            out.append(('case-' + name, case_invalid(fn)))
    return out


def main():
    bad = 0
    for name, fn in SCENARIOS.items():
        req = fn()
        raw = json.dumps(req, separators=(',', ':')).encode()
        res = subproc(raw)
        try:
            verify.verify_response(req, res)
            print('OK  ', name)
        except verify.Fail as e:
            bad += 1
            print('FAIL', name, ':', e)
            with open('/workspace/fuzz/casefail_%s.json' % name, 'w') as f:
                json.dump({'request': req, 'response': res}, f)
    for name, payload in build_invalid():
        data = payload if isinstance(payload, bytes) else payload.encode()
        res = subproc(data)
        if res != {'error': 'invalid_request'}:
            bad += 1
            print('FAIL invalid', name, '->', json.dumps(res)[:120])
        else:
            print('OK   invalid', name)
    print('cases done bad=%d' % bad)
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
